vulnerable_code:
app.get('/api/orders/download', (req, res) => {
  Order.findOne({ _id: req.query.id }, (err, order) => {
    if (err || !order) return res.status(404).send();
    res.download(order.invoiceFilePath);
  });
});

corrected_code:
app.get('/api/orders/download', (req, res) => {
  Order.findOne({ _id: req.query.id, userId: req.session.userId }, (err, order) => {
    if (err || !order) return res.status(404).send();
    res.download(order.invoiceFilePath);
  });
});
